// 地図 (canvas) に描くアイコン: 色を塗った SVG を画像にして使い回す。読み込めたら星系図を描き直す
const ICON_IMG = new Map();
function iconImg(k, color) {
  const key = `${k}|${color}`;
  let im = ICON_IMG.get(key);
  if (!im && ICONS[k]) {
    im = new Image();
    im.onload = () => { if (typeof systemView !== 'undefined') systemView.animating = true; };
    im.src = `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${ICONS[k][0]}" width="64" height="64" fill="${color}" color="${color}">${ICONS[k][1]}</svg>`)}`;
    ICON_IMG.set(key, im);
  }
  return im?.complete && im.naturalWidth ? im : null;
}
